create function pg_temp.fail_review_audit() returns trigger language plpgsql as $$ begin
 if new.action='listing.approved' then raise exception 'Synthetic audit failure'; end if; return new; end $$;
create trigger synthetic_audit_failure before insert on private.audit_logs for each row execute function pg_temp.fail_review_audit();
set local role authenticated;
set local request.jwt.claims='{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","aal":"aal2","user_metadata":{"role":"admin","aal":"aal2"}}';
