-- Defer the invariant to prove approval independently refuses missing photos.
set constraints all deferred;
create temp table removed_photo as select * from public.listing_media where listing_id=(select id from review_fixture where name='rollback');
delete from public.listing_media where listing_id=(select id from review_fixture where name='rollback');
set local role authenticated;
select throws_ok($$select public.admin_approve_listing((select id from review_fixture where name='rollback'),1,1,3,'[]')$$,'23514',null,'approval independently enforces photo count');
reset role;
insert into public.listing_media(id,listing_id,owner_id,media_id,sort_order) select id,listing_id,owner_id,media_id,sort_order from removed_photo;
set constraints all immediate;
-- Existing approval snapshots must update atomically on another review cycle.
update public.listings set published_at='2020-01-01' where id=(select id from review_fixture where name='approve');
set local role authenticated;
set local request.jwt.claims='{"sub":"11111111-1111-4111-8111-111111111111"}';
